+// hashTokenSecret returns a single-pass SHA-256 of the salt followed by the
+// token secret. Token secrets are 32 random bytes, so they need no key
+// stretching; only passwords go through hashSecret.
+func hashTokenSecret(secret string, salt []byte) []byte {
+	h := sha256.New()
+	h.Write(salt)
+	h.Write([]byte(secret))
+	return h.Sum(nil)
+}
